mapper.select:
SELECT /*selectMasterWmGiTrReleaseRecordList*/
X.BUYER_NAME, X.AGENT_NAME, X.CNT, X.AMT, X.BUYER, X.AGENT, X.WAREHOUSE_CODE FROM ( SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = WIDT.BUYER)) AS BUYER_NAME, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = WIDT.AGENT)) AS AGENT_NAME, COUNT(WIDT.INV_SEQ) AS CNT, SUM(ROUND(NVL(WIDT.DELIVERY_QTY,0) * NVL(WIDT.UNIT_PRICE,0),3)) AS AMT, WIDT.BUYER AS BUYER, WIDT.AGENT AS AGENT, WIDT.WAREHOUSE_CODE AS WAREHOUSE_CODE
FROM WMSIVDT WIDT WHERE WIDT.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND WIDT.WAREHOUSE_CODE =#{st_warehouse_code}
AND (WIDT.BUYER LIKE 'KRXPR0%' OR WIDT.BUYER = 'KRXPV00001')
AND WIDT.BUYER IN
#{st_buyer_code}
AND WIDT.STATUS <> 'D' GROUP BY WIDT.WAREHOUSE_CODE,WIDT.BUYER,WIDT.AGENT
ORDER BY 7,1,2
ORDER BY 7,2,1
)X
